---FreshUI
---@param deliveryId2Data table 培育Id->培育数据
---@param deliveryId number     培育Id
function CatHouseCultivationCatNode:FreshUI(deliveryId2Data, deliveryId, deliveryId2CultivationType)
    ----------------------------
    --- 数据处理
    local cultivationType = deliveryId2CultivationType[deliveryId]
    if self.cultivationType == CultivationType.Lock and cultivationType == CultivationType.CanLock then
        self.unlockCo = cs_coroutine.start(function()
            ---@type UnityEngine.Animator
            local coverNode = self.coverNode
            KTool.SetActive(coverNode.gameObject, true)
            coverNode:SetBool(AnimatorFlag, true)
            cs_coroutine.yield_return()
            cs_coroutine.yield_return(coverNode:WaitUntilAniCompleted())
            KTool.SetActive(coverNode, false)
            self.unlockCo = nil
        end)

    end
    if self.cultivationType == cultivationType then
        if cultivationType == CultivationType.FriendsConfirming then
            self:FreshFriendConfirmTextTime()
        elseif cultivationType == CultivationType.Hatching then
            self:FreshHatchingTextTime()
        end
        return
    end
    self.deliveryId         = deliveryId
    self.deliveryId2Data    = deliveryId2Data
    self.cultivationType    = cultivationType
    self.deliveryId2CultivationType = deliveryId2CultivationType

    ----------------------------
    --- UI显示
    self:ShowUI()

    return
end

function CatHouseCultivationCatNode:ShowUI()

    local cultivationType         = self.cultivationType
    local isAdd                   = cultivationType == CultivationType.Add
    local isFriendsConfirming     = cultivationType == CultivationType.FriendsConfirming
    local isFriendsConfirmingFail = cultivationType == CultivationType.FriendsConfirmingFail
    local isHatching              = cultivationType == CultivationType.Hatching
    local isRequestFail           = cultivationType == CultivationType.RequestFail
    local isReceive               = cultivationType == CultivationType.Receive

    -----------------------------------
    --- CanLock 和 Lock 需要更新模型显示
    local isCanLock               = cultivationType == CultivationType.CanLock
    local isLock                  = cultivationType == CultivationType.Lock

    KTool.SetActive(self.Add.gameObject, isAdd)
    --KTool.SetActive(self.L/ .gameObject, isAdd)

    KTool.SetActive(self.CanUnlock.gameObject, isCanLock and self.privilegeRewardsVo == nil)
    KTool.SetActive(self.CardUnlock.gameObject, isCanLock and self.privilegeRewardsVo ~= nil)
    KTool.SetActive(self.FriendConfirm.gameObject, isFriendsConfirming)
    if isFriendsConfirming then
        self:FreshFriendConfirmTextTime()
    end

    KTool.SetActive(self.RequestFail.gameObject, isFriendsConfirmingFail or isRequestFail)
    if isFriendsConfirmingFail or isRequestFail then
        self.RequestFailText.text = localize("请求失败")
        --- 孵化消耗道具id
        local goodsId = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.HatchConsumeId).num)
        ---@type GoodsVo
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        self.RequestFailImgIcon:LoadSprite(goodsVo.photoPath)
    end

    KTool.SetActive(self.Hatching.gameObject, isHatching)
    if isHatching then
        self:FreshHatchingTextTime()
    end

    KTool.SetActive(self.CanReceive.gameObject, isReceive)

    self.Root:Play(isLock and HashLock or (isCanLock and HashUnlock or HashIdle))

    --- 如果是孵化中 要移除猫 因为可能是从 好友确认 -> 孵化中
    if not (isReceive or isFriendsConfirming or isFriendsConfirmingFail) then
        self:RemoveCatEgg()
    end

    if isHatching or isReceive or isFriendsConfirming or isFriendsConfirmingFail then
        self:LoadCatEgg(isFriendsConfirming, isHatching)
    end
end

function CatHouseCultivationCatNode:FreshFriendConfirmTextTime()
    local deliveryData = self:GetDeliveryData()
    if deliveryData == nil then return end
    self.FriendConfirmTextTime.text = GetTimeHMS2(deliveryData.remainTime)
end

function CatHouseCultivationCatNode:FreshHatchingTextTime()
    local deliveryData = self:GetDeliveryData()
    if deliveryData == nil then return end
    self.HatchingTextTime.text = GetTimeHMS2(deliveryData.remainTime)
end

