---ClearDeliveryData
---清理培育数据
function CatHouseCultivationCatNode:ClearDeliveryData()
    ---@type CatHouseComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)

    if self.privilegeRewardsVo then
        --- 如果是特权位置
        --- 1.1 检查是否还有特权卡
        -- local catHouseHomeDojo = component:GetCatHouseHomeDojo()
        local expirationTime   = component:GetPrivilegeCardSecondsById(self.privilegeRewardsVo.id)
        --- 1.2 移除 deliveryList 数据
        self.deliveryId2Data[self.deliveryId] = component:ClearDeliveryDataById(self.deliveryId)
        if expirationTime > 0 then

            --- 1.3 更新本地数据
            self:UpdateCultivationType(CultivationType.Add)
        else
            -- --- 1.2 移除 deliveryList 数据
            -- self.deliveryId2Data[self.deliveryId] = component:ClearDeliveryDataById(self.deliveryId)

            --- 1.3 更新本地数据
            self:UpdateCultivationType(CultivationType.CanLock)
        end
    else
        --- 1.2 移除 deliveryList 数据
        self.deliveryId2Data[self.deliveryId] = component:ClearDeliveryDataById(self.deliveryId)

        --- 1.3 更新本地数据
        self:UpdateCultivationType(CultivationType.Add)
    end
end

---RequestFriendCancel
---主动或被动取消好友配对
---@param reqData table<string, number> {deliveryId = deliveryId}
function CatHouseCultivationCatNode:RequestFriendCancel(reqData)
    GameUtils.Request(Interfaces.CatHouseFriendCancel, reqData, function(req, response)
        ------------------------
        --- 1.处理数据
        --- 1.1  更新奖励
        local rewards = response.data.rewards
        GoodsUtils.DrawRewards(rewards)

        --- 1.2 移除倒计时相关数据
        ---@type CatHouseComponent
        local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
        component:UpdateCDData(self:GetDeliveryData().playerCatId, ConstantsCatHouse.CatStatus.Waiting)

        --- 1.3 移除培育 相关数据
        self:ClearDeliveryData()

        ---1.4 更新培育红点
        component:UpdateDeliveryRedPoint()

        ------------------------
        --- 2.刷新UI
        self:ShowUI()

        ------------------------
        --- 3.显示打脸
        UIModule.OpenDialog({id = Constants.UITypeIds.UICommonRewardPop, parameters = {rewards = rewards}})
    end)
end

---RequestReceiveCat
---@param reqData table<string, number> {deliveryId = deliveryId}
function CatHouseCultivationCatNode:RequestReceiveCat(reqData)
    GameUtils.Request(Interfaces.CatHouseReceiveCat, reqData, function(req, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        ------------------------
        --- 1.处理数据

        -- local response = table.deserialize([[{"data":{"cat":{"name":"\u4e0d\u5b66\u65e0\u672f\u7684\u82b1\u82b1","petId":104,"age":1,"genes":[{"geneId":1104,"skillId":0,"additions":0},{"geneId":1204,"skillId":0,"additions":0},{"geneId":2301,"skillId":0,"additions":0},{"geneId":1401,"skillId":0,"additions":0},{"geneId":1504,"skillId":0,"additions":0},{"geneId":1603,"skillId":0,"additions":0}],"isVariation":0,"isShow":0,"attr":{"1":"0","2":"0","3":"0","4":"0"},"birthday":"2022-09-24 00:00:02","playerId":1000272,"trainingTimes":0,"deleted":0,"createTime":"2022-08-22 15:40:28","id":"35096","status":[],"deliveryRemainTimes":5,"catId":104}},"timestamp":1663948802,"errCode":0,"errMsg":""}]])

        --- 1.1 移除倒计时相关数据 移除孩子孵化中倒计时
        ---@type CatHouseComponent
        local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
        local deliveryData = self:GetDeliveryData()
        local playerCatId = checkNumber(deliveryData.childPlayerCatId)
        component:UpdateCDData(playerCatId, ConstantsCatHouse.CatStatus.Hatching)

        -- pri
        -- component:SetCatDataById(playerCatId, response.data.cat)
        --- 1.2 找到猫数据中 幼年期表现出来的id 并 插入到全局缓存中
        
        
        local catData = component:GetCatDataById(playerCatId)
        catData.birthday = response.data.cat.birthday
        local genes = catData.genes
        for i, v in ipairs(genes) do
            local geneId = v.geneId
            ---@type CatHouseCatDataVo
            local catDataVo = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", geneId)
            local infancyUnlock = catDataVo.infancyUnlock == 1
            if infancyUnlock then
                component:AddUnlockedGene(geneId)
            end
        end

        --- 1.3 移除培育 相关数据
        self:ClearDeliveryData()

        ---1.4 更新培育红点
        component:UpdateDeliveryRedPoint()
        ------------------------
        --- 2.刷新UI
        self:ShowUI()

        ------------------------
        --- 3.进入领取成功界面
        UIModule.OpenDialog({ id = Constants.UITypeIds.CatHouseCultivationGetCatPopup, parameters = {viewType = 1, playerCatId = playerCatId}})

    end)
end

