function CatHouseCultivationCatNode:LoadCatEgg(isFriendsConfirming)

    if not isNull(self.go) then
        self:InitCatEggTransform()
        return
    end

    local catEggName = self:GetEggName(isFriendsConfirming)
    if string.isEmpty(catEggName) then return end

    local assetPath = string.format("Arts/Prefab_cat/Prefab_catparts/%s.prefab", catEggName)
    local go = GameUtils.LoadBundleSync(assetPath, self.cultivationModel.gameObject, false)
    if isNull(go) then return end
    self.go = go
    self:InitCatEggTransform()

end

function CatHouseCultivationCatNode:GetEggName(isFriendsConfirming)
    local deliveryData = self:GetDeliveryData()
    --- 处于好友确认中无幼猫id  只能使用母猫id 来取空壳
    local playerCatId = isFriendsConfirming and checkNumber(deliveryData.playerCatId) or checkNumber(deliveryData.childPlayerCatId)
    if playerCatId <= 0 then return end
    ---@type CatHouseComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
    local catData = component:GetCatDataById(playerCatId)
    local catId   = catData.catId
    ---@type CatHouseCatVo
    local catHouseCatVo = CfUtils.GetCfVo(AutoIds.IdSetting1906, "CatHouseCatVo", catId)
    return isFriendsConfirming and catHouseCatVo.ghostCatEgg or catHouseCatVo.catEgg
end

function CatHouseCultivationCatNode:InitCatEggTransform()
    local config = CultivationModelTansConfig[self.deliveryId]
    local hatchPos, receivePos, scale, rotation = SafeUnpack(config)
    local isReceive = self.cultivationType == CultivationType.Receive
    local transform  = self.go.transform
    transform.localScale    = scale
    transform.localRotation = rotation
    transform.localPosition = isReceive and receivePos or hatchPos
end

function CatHouseCultivationCatNode:RemoveCatEgg()
    if not isNull(self.go) then
        KTool.SafeDelete(self.go.gameObject)
        self.go = nil
        -- self.loader:Release(true)
        -- self.loader = nil
    end
end

