function CatHouseCultivationCatNode:OnClickNodeAction()

    local cultivationType = self.cultivationType

    if cultivationType == CultivationType.Lock then
        GameUtils.Toast(localize("该孵化位置未解锁"))

    elseif cultivationType == CultivationType.Add then
        --local deliveryData    = self:GetDeliveryData()

        ---1. 进入配对弹窗
        self:EnterMatchView()

    elseif cultivationType == CultivationType.FriendsConfirming then
        --local deliveryData    = self:GetDeliveryData()
        self:EnterMatchView()

    elseif cultivationType == CultivationType.FriendsConfirmingFail or cultivationType == CultivationType.RequestFail then
        local deliveryId = self.deliveryId
        self:RequestFriendCancel({ deliveryId = deliveryId})

    elseif cultivationType == CultivationType.Receive then
        ---1.检查背包
        ---@type CatHouseComponent
        local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
        ---@type CatHouseHomeDojo
        local catHouseHomeDojo = component:GetCatHouseHomeDojo()
        --- 猫咪列表空位上限
        local catHouseCatNum = CatHouseMgr:GetInstance():GetCatNum()
        
        if catHouseCatNum >= checkNumber(catHouseHomeDojo.maxCatsNum) then
            if catHouseCatNum < CatHouseMgr:GetInstance():GetCatListUpLimit() then
                ---todo 以后可能会直接扩容
            end
            GameUtils.Toast(localize("当前猫咪列表已达上限"))
            return
        end
        local deliveryId = self.deliveryId
        self:RequestReceiveCat({ deliveryId = deliveryId})

    elseif cultivationType == CultivationType.CanLock then
        if self.privilegeRewardsVo then
            ---todo 下版本才上特权卡
            self:HandlePrivilegeCardBuy(self.privilegeRewardsVo)

        else
            --- 孵化每次扩充消耗道具id
            local goodsId = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.HatchExpansionConsumeId).num)
            --- 孵化每次扩充消耗道具数量
            local goodsNum = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.HatchExpansionConsumeNum).num)
            ---@type GoodsVo
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            GameUtils.SecondConfirm(localize("是否花费_num__name_解锁", {_num_ = goodsNum, _name_ = goodsVo.name}), function()
                --- 1. 检查解锁道具是否足够
                local consume, errTip = GoodsUtils.CheckGoodConsume({ { goodsId = goodsId, goodsNum = goodsNum } })
                if errTip then
                    GameUtils.Toast(errTip)
                    return
                end
                --- 2. 发送 解锁请求
                self:RequestUnlockLiveryLimit(consume)
            end)


        end


    end

end

